WFJ.Data.add("spell", {
  [400009] = { "遠隔攻撃のFinishing move。コンボポイントに応じたダメージを与え、ダメージはAttack Powerで増加します。さらに対象をStunさせます：\n\n$N1ポイント：$N2のダメージ、$N3秒間Stun\n $N4ポイント：$N5のダメージ、$N6秒間Stun\n $N7ポイント：$N8のダメージ、$N9秒間Stun\n $N10ポイント：$N11のダメージ、$N12秒間Stun\n $N13ポイント：$N14のダメージ、$N15秒間Stun\n\nKidney Shotとクールダウンを共有します。", "スタンしています。", 0x658894d6, 0x27f95286, "uu" },
  [400012] = { "フィニッシュ技。Parry率を$N1%上昇させ、防御スキルが$N3を超える1ポイントごとにAttack Powerを$N2付与します。コンボポイントが多いほど長く持続します：\n\n$N4ポイント：$N5秒\n $N6ポイント：$N7秒\n $N8ポイント：$N9秒\n $N10ポイント：$N11秒\n $N12ポイント：$N13秒", { "受け流し率が$N1%上昇しています。受ける物理ダメージが$N2%減少しています。", "受け流し率が$N1%上昇しています。", shape = { "2/0", "1/0" } }, 0xc4b7b86b, 0x43cd9880, "uu" },
  [400080] = { "胸部か法衣にDeadly Brewのルーンを刻みます：\r\n\n$I1\r\n毒がいくつか強化されます：\r\n\n対象に他の毒を与えると、Deadly Poisonも与えます。\r\n\n武器に毒が付与されていない場合、Instant Poisonが付与されているかのように、一定の確率でInstant Poisonが発動します。\r\n\nDeadly PoisonとInstant PoisonのダメージがAttack Powerによって増加するようになります。\r\n\n他のローグのDeadly Poisonを受けている対象にも、自分のDeadly Poisonが有効になります。", nil, 0x1a66a12e, nil, "um" },
  [400081] = { "脚部にBetween the Eyesのルーンを刻みます：\r\n\n$I1\r\nコンボポイントごとにダメージを与え、Attack Powerによって増加し、対象をStunさせる遠隔Finishing moveです：\r\n\n1ポイント：$N2のダメージ、1秒のStun\r\n 2ポイント：$N5のダメージ、2秒のStun\r\n 3ポイント：$N8のダメージ、3秒のStun\r\n 4ポイント：$N11のダメージ、4秒のStun\r\n 5ポイント：$N14のダメージ、5秒のStun\r\n\nKidney Shotとクールダウンを共有します。", nil, 0x7fe6c87f, nil, "um" },
  [400082] = { "胸部か法衣にJust a Flesh Woundのルーンを刻みます：\r\n\n$I1\r\nBlade Danceが有効な間、受けるPhysicalダメージが$N1%減少し、さらにDefenseスキルが$N4を超える分$N3ごとに1%減少します。さらに、Dodge率が$N5%倍になり、近接攻撃でクリティカルヒットを受ける確率が$N6%減少し、与えるダメージが$N7%減少し、すべての行動で発生する脅威が大幅に増加し、FeintのアビリティがTeaseに置き換わります。Teaseは対象をTauntして自分を攻撃させます。\r\n\n$I2\r\n対象をTauntして自分を攻撃させますが、対象がすでに自分を攻撃している場合は効果がありません。", nil, 0xd37806b5, nil, "um" },
  [400093] = { "ブーツにRolling with the Punchesのルーンを刻みます：\r\n\n$I1\r\nDodgeまたはParryするたびにHealthが$N1%増加します。最大$N2回まで累積します。", nil, 0xdc8b0d48, nil, "um" },
  [400094] = { "手袋にMutilateのルーンを刻みます：\r\n\n$I1\r\n両方の武器で即座に攻撃し、$N1%の武器ダメージに加えて、それぞれの武器で$N2の追加ダメージを与えます。Poisoned状態の対象へのダメージが$N3%増加します。Combo Pointを$N4獲得します。", nil, 0xb45a10bc, nil, "um" },
  [400095] = { "胸部か法衣にQuick Drawのルーンを刻みます：\r\n\n$I1\r\n遠隔武器を抜いて敵に素早く射撃し、通常の遠隔武器ダメージを与え、$D1の間、対象の移動速度を$N1%低下させます。コンボポイントを$N3獲得します。\r\n\nQuick Drawは、Sinister Strikeによって発動する、またはSinister Strikeを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0x0baef149, nil, "um" },
  [400096] = { "ベルトにShuriken Tossのルーンを刻みます：\r\n\n$I1\r\n敵に手裏剣を投げ、Attack Powerの$N1%に等しいダメージを与え、さらに近くの対象を最大$N2体攻撃します。命中した対象ごとにコンボポイントを$N3獲得します。", nil, 0xf3dd9623, nil, "um" },
  [400099] = { "脚部にBlade Danceのルーンを刻みます：\r\n\n$I1\r\nParry率を$N1%上昇させ、Defenseスキルが$N3を超えるポイントごとにAttack Powerを$N2与えるフィニッシュ技です。コンボポイントが多いほど効果時間が長くなります：\r\n\n1ポイント：14秒\r\n 2ポイント：18秒\r\n 3ポイント：22秒\r\n 4ポイント：26秒\r\n 5ポイント：30秒", nil, 0xde49cba0, nil, "um" },
  [400101] = { "ベルトにShadowstepのルーンを刻みます：\r\n\n$I1\r\n影の中を進んで敵の背後に再び現れようと試み、$D1の間、移動速度を$N1%上昇させます。", nil, 0x40b18911, nil, "um" },
  [400104] = { "脚部にShadowstepのルーンを刻みます：\r\n\n$I1\r\n影の中を進んで敵の背後に再び現れようと試み、$D1の間、移動速度を$N1%上昇させます。", nil, 0x70e32775, nil, "um" },
  [400105] = { "手袋にShadowstrikeのルーンを刻みます：\r\n\n$I1\r\n対象の背後にテレポートして攻撃し、対象に$N1%の武器ダメージを与えます。ステルス状態である必要があります。コンボポイントを$N2獲得します。", nil, 0xdfa82ca8, nil, "um" },
  [400574] = { "対象をエネルギーで攻撃し、$N1のArcaneダメージを与えます。Arcane Blastを唱えるたびに、他のすべての呪文のダメージが$N2%増加し、Arcane Blastのmanaコストが$N3%増加します。この効果は最大$N4回まで重なり、$D1経過するか、他のダメージ呪文を唱えるまで持続します。", nil, 0x70a83dc8, nil, "um" },
  [400588] = { "Arcane Blastに$N1%、Fireball、Frostbolt、Frostfire Boltに$N2%の確率を与え、次のArcane Missilesの詠唱時間を$N3%短縮し、Manaコストを$N4%軽減し、ミサイルが$N5秒ごとに発射されるようにします。", nil, 0xbb498da4, nil, "um" },
  [400610] = { "対象の敵に複数のミサイルを放ち、$N1のArcaneダメージを与えます。この呪文は$N2%の確率でMissile Barrageを発動させます。", nil, 0x5529aca1, nil, "um" },
  [400613] = { "対象はLiving Bombとなり、$D1かけて$N1のFireダメージを受けます。$D2経過するか呪文が解除されると対象は爆発し、$N5ヤード以内のすべての敵に$N4のFireダメージを与えます。\n\nLiving BombはScorchで発動する、またはScorchを変化させるすべてのタレントと効果の恩恵を受けます。", "$N2秒ごとに$N1のFireダメージを受けています。$D2が経過するか呪文が解除されると、対象は爆発し、$N5ヤード以内のすべての敵に$N4のFireダメージを与えます。", 0xc69cd4f9, 0x756c2ee6, "uu" },
  [400614] = { "対象はLiving Bombとなり、$D1かけて$N1のFireダメージを受けます。$D2経過するか呪文が解除されると対象は爆発し、$N5ヤード以内のすべての敵に$N4のFireダメージを与えます。", nil, 0xe9008f20, nil, "um" },
