  [400624] = { "Fireball、Frostfire Bolt、Fire Blast、Scorchの持続型でないクリティカルで、$D1の間Hot Streakを得ます。Hot StreakはPyroblastの詠唱時間を$N2%短縮し、最大$N3回まで重なります。", nil, 0x0ff8c902, nil, "um" },
