  [400647] = { "Chill効果に$N1%の確率でFingers of Frost効果を得る力を与えます。Fingers of Frostは、次に唱える$N2回の呪文を対象がFrozenであるかのように扱います。効果時間は$D1です。", nil, 0x57768bb5, nil, "um" },
